//! Cross-language golden tests using imported fixtures.
//!
//! These tests consume the imported fixtures in place; they do not edit or
//! duplicate them. Expected digests are pinned from the fixtures, not
//! generated by the Rust implementation under test.

use dolly_canonical_json::{ParseLimits, canonicalize, parse_core_json};
use std::path::PathBuf;

fn spec_dir() -> PathBuf {
    PathBuf::from("../../dolly-spec")
}

fn read_fixture(rel: &str) -> Vec<u8> {
    std::fs::read(spec_dir().join(rel))
        .unwrap_or_else(|e| panic!("failed to read fixture {rel}: {e}"))
}

// ---------------------------------------------------------------------------
// TST-CONFIG-003: effective config overlay
// ---------------------------------------------------------------------------

#[test]
fn tst_config_003_canonical_bytes_and_digest() {
    // The test verifies canonical bytes for {"cache":{"module":true},"inherited":1,"nullable":null,"tags":["module"]}
    let test_value = parse_core_json(
        br#"{"cache":{"module":true},"inherited":1,"nullable":null,"tags":["module"]}"#,
        ParseLimits::protocol_wire(),
    )
    .unwrap();
    let (bytes, digest) = canonicalize(&test_value).unwrap();

    // Verify canonical bytes
    let canonical_str = String::from_utf8(bytes.into_vec()).unwrap();
    assert_eq!(
        canonical_str,
        r#"{"cache":{"module":true},"inherited":1,"nullable":null,"tags":["module"]}"#
    );

    // Verify digest
    assert_eq!(
        digest.to_canonical_string(),
        "sha256:75d72a950e3a0e5a7ad5150b6a52bfc4f2bc83c001c23dd7d44045b13149d223"
    );
}

