// ---------------------------------------------------------------------------
// TST-CORE-009: activation ledger evidence digest
// ---------------------------------------------------------------------------

#[test]
fn tst_core_009_activation_ledger_evidence_digest() {
    let fixture_bytes =
        read_fixture("test-vectors/core/TST-CORE-009-activation-ledger-evidence.json");
    let fixture = parse_core_json(&fixture_bytes, ParseLimits::protocol_wire()).unwrap();

    // Navigate to stimulus.cases.complete.commands[1].record
    let obj = match &fixture {
        dolly_canonical_json::CanonicalJsonValue::Object(o) => o,
        _ => panic!("fixture should be an object"),
    };

    let stimulus = obj.get("stimulus").unwrap();
    let stimulus_obj = match stimulus {
        dolly_canonical_json::CanonicalJsonValue::Object(o) => o,
        _ => panic!("stimulus should be an object"),
    };

    let cases = stimulus_obj.get("cases").unwrap();
    let cases_obj = match cases {
        dolly_canonical_json::CanonicalJsonValue::Object(o) => o,
        _ => panic!("cases should be an object"),
    };

    let complete = cases_obj.get("complete").unwrap();
    let complete_obj = match complete {
        dolly_canonical_json::CanonicalJsonValue::Object(o) => o,
        _ => panic!("complete should be an object"),
    };

    let commands = complete_obj.get("commands").unwrap();
    let commands_arr = match commands {
        dolly_canonical_json::CanonicalJsonValue::Array(a) => a,
        _ => panic!("commands should be an array"),
    };

    // The second command (index 1) contains the record and expected_evidence_digest
    let cmd = &commands_arr[1];
    let cmd_obj = match cmd {
        dolly_canonical_json::CanonicalJsonValue::Object(o) => o,
        _ => panic!("command should be an object"),
    };

    let record = cmd_obj.get("record").unwrap();
    let expected_digest = match cmd_obj.get("expected_evidence_digest") {
        Some(dolly_canonical_json::CanonicalJsonValue::String(s)) => s.clone(),
        _ => panic!("expected_evidence_digest should be a string"),
    };

    // Compute the digest of the record
    let (_bytes, digest) = canonicalize(record).unwrap();
    assert_eq!(
        digest.to_canonical_string(),
        expected_digest,
        "activation ledger evidence digest mismatch"
    );
}

// ---------------------------------------------------------------------------
// protocol/examples/valid-module-activate.json: manifest_digest and effective_config_digest
// ---------------------------------------------------------------------------

#[test]
fn valid_module_activate_manifest_digest() {
    let fixture_bytes = read_fixture("protocol/examples/valid-module-activate.json");
    let fixture = parse_core_json(&fixture_bytes, ParseLimits::protocol_wire()).unwrap();

    let obj = match &fixture {
        dolly_canonical_json::CanonicalJsonValue::Object(o) => o,
        _ => panic!("fixture should be an object"),
    };

    let params = obj.get("params").unwrap();
    let params_obj = match params {
        dolly_canonical_json::CanonicalJsonValue::Object(o) => o,
        _ => panic!("params should be an object"),
    };

    let manifest = params_obj.get("manifest").unwrap();
    let manifest_obj = match manifest {
        dolly_canonical_json::CanonicalJsonValue::Object(o) => o,
        _ => panic!("manifest should be an object"),
    };

    // Get the declared manifest_digest
    let declared_digest = match manifest_obj.get("manifest_digest") {
        Some(dolly_canonical_json::CanonicalJsonValue::String(s)) => s.clone(),
        _ => panic!("manifest_digest should be a string"),
    };

    // Compute the digest of the manifest with manifest_digest omitted:
    // rebuild the object without manifest_digest.
    let mut members: Vec<(String, dolly_canonical_json::CanonicalJsonValue)> = Vec::new();
    for (key, value) in manifest_obj.iter() {
        if key != "manifest_digest" {
            members.push((key.to_string(), value.clone()));
        }
    }
    let manifest_without_digest_obj =
        dolly_canonical_json::CanonicalJsonObject::try_from_iter(members).unwrap();
    let manifest_without_digest_value =
        dolly_canonical_json::CanonicalJsonValue::Object(manifest_without_digest_obj);

    let (_bytes, digest) = canonicalize(&manifest_without_digest_value).unwrap();
    assert_eq!(
        digest.to_canonical_string(),
        declared_digest,
        "manifest_digest mismatch"
    );
}

